const fs = require('fs');
const path = require('path');

const BASE_DIR = '/tmp/resources';

function saveDataSnapshot(category, fileName, data) {
  const resolvedPath = path.resolve(BASE_DIR, category, fileName);

  if (!resolvedPath.startsWith(path.resolve(BASE_DIR) + path.sep)) {
    throw new Error('Invalid path: snapshot must be saved within the base directory.');
  }

  const dir = path.dirname(resolvedPath);

  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  fs.writeFileSync(resolvedPath, data, 'utf8');
}


